from pathlib import Path

path = Path('writing/benevolent_outsider_draft_04_method_primitive_1921_1933.md')
text = path.read_text(encoding='utf-8')
old = "Late 1933 adds another route, this time returning explicitly to *primitive*. On 27 October Huizinga wrote Malinowski that he had come across a review of Sjoerd Hofstra’s *Differenzierungserscheinungen in einigen afrikanischen Gruppen: Ein Beitrag zur Frage der primitiven Individualität*; Malinowski replied three days later.[^19] On 6 November, in an Amsterdam lecture on Renaissance and ‘new time’, Huizinga wrote that when humanity means the future it often cries ‘back’, then footnoted Hofstra’s citation of W. C. Willoughby’s prophet among *natuurvolken* calling people to return to old loyalties because the ideal age lay in the past (Huizinga, 1934). The ethnographic example supplied a relation—return to an idealized past—to a general historical claim. The people described as primitive did not have to stand simply as Europe’s past."
new = "Late 1933 adds another route, this time returning explicitly to *primitive*. On 27 October Huizinga wrote Malinowski that he had come across a review of Sjoerd Hofstra’s *Differenzierungserscheinungen in einigen afrikanischen Gruppen: Ein Beitrag zur Frage der primitiven Individualität*; Malinowski replied three days later.[^19] The Amsterdam lecture Huizinga delivered on 6 November began from a problem of naming. The great objects of cultural history, he wrote, were so complex and diffuse that they could not properly bear a name or be grasped as a closed unity, yet without names history could not make them visible to the mind; such names often arose from the wishes and imagination of the age itself (Huizinga, 1934). He then wrote that when humanity means the future it often cries ‘back’, and footnoted Hofstra’s citation of W. C. Willoughby’s prophet among *natuurvolken* calling people to return to old loyalties because the ideal age lay in the past. The ethnographic example supplied a relation—return to an idealized past—to a general historical claim. The people described as primitive did not have to stand simply as Europe’s past."
if text.count(old) != 1:
    raise SystemExit(f'anchor count={text.count(old)}')
path.write_text(text.replace(old, new, 1), encoding='utf-8')
